"use client"

import * as React from "react"
import { Switch as SwitchPrimitive } from "@base-ui/react/switch"

import { cn } from "@/lib/utils"

// Amber Glass Switch: recessed well track; checked, the track lights up with
// the same amber material as the primary Button (gradient + rim + glow).

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Switch = React.forwardRef<
  HTMLButtonElement,
  WithClassName<SwitchPrimitive.Root.Props>
>(({ className, ...props }, ref) => (
  <SwitchPrimitive.Root
    className={cn(
      "group/switch peer inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-full",
      "transition-all duration-fast ease-out",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
      "data-disabled:cursor-not-allowed data-disabled:opacity-50",
      "data-unchecked:bg-[var(--ag-well)] data-unchecked:border data-unchecked:border-[color:var(--ag-border-strong)] data-unchecked:shadow-[var(--shadow-well)]",
      "data-checked:bg-[image:var(--ag-primary-grad)] data-checked:border-0 data-checked:shadow-[var(--shadow-primary)]",
      className
    )}
    {...props}
    ref={ref}
  >
    <SwitchPrimitive.Thumb
      className={cn(
        "pointer-events-none block h-4 w-4 rounded-full",
        "bg-[oklch(0.97_0.005_85)]",
        "shadow-[0_0.0625rem_0.125rem_oklch(0_0_0/0.4),inset_0_0.0625rem_0_oklch(1_0_0/0.5)]",
        "ring-0",
        "data-checked:translate-x-4 data-unchecked:translate-x-0.5",
        "origin-left data-checked:origin-right rtl:origin-right rtl:data-checked:origin-left transition-[translate,scale,transform-origin,background-color,box-shadow] duration-[260ms,140ms,0ms,150ms,150ms] delay-[0ms,0ms,140ms,0ms,0ms] ease-out motion-safe:group-active/switch:scale-x-[1.18] motion-reduce:transition-none"
      )}
    />
  </SwitchPrimitive.Root>
))
Switch.displayName = "Switch"

export { Switch }
